DELETE FROM lesson WHERE material_id IN ( SELECT id FROM lesson_material WHERE document LIKE '%material-asset:%' OR document LIKE '%data:image%' OR id IN ( SELECT material_id FROM material_asset WHERE external_url LIKE 'data:image%' ) ) OR lesson_template_id IN ( SELECT id FROM lesson_template WHERE material_id IN ( SELECT id FROM lesson_material WHERE document LIKE '%material-asset:%' OR document LIKE '%data:image%' OR id IN ( SELECT material_id FROM material_asset WHERE external_url LIKE 'data:image%' ) ) );
DELETE FROM lesson_template WHERE material_id IN ( SELECT id FROM lesson_material WHERE document LIKE '%material-asset:%' OR document LIKE '%data:image%' OR id IN ( SELECT material_id FROM material_asset WHERE external_url LIKE 'data:image%' ) );
DELETE FROM assignment WHERE material_id IN ( SELECT id FROM lesson_material WHERE document LIKE '%material-asset:%' OR document LIKE '%data:image%' OR id IN ( SELECT material_id FROM material_asset WHERE external_url LIKE 'data:image%' ) );
